import { Injectable, Module } from "@nestjs/common"
import { NestFactory } from "@nestjs/core"

@Injectable() class TaxCalculator { tax(x: number) { return Math.round(x * 0.12) } }         // ichki
@Injectable() class RoundingPolicy { round(x: number) { return Math.round(x / 100) * 100 } } // ichki

@Injectable()
class BillingFacade {
    constructor(private readonly tax: TaxCalculator, private readonly rounding: RoundingPolicy) {}
    total(amount: number) { return this.rounding.round(amount + this.tax.tax(amount)) }
}

@Module({ providers: [TaxCalculator, RoundingPolicy, BillingFacade], exports: [BillingFacade] })
class BillingModule {}

@Injectable() class Checkout { constructor(readonly billing: BillingFacade) {} }
@Module({ imports: [BillingModule], providers: [Checkout] })
class CheckoutModule {}

@Module({ imports: [CheckoutModule] })
class AppModule {}

async function main() {
    const app = await NestFactory.createApplicationContext(AppModule, { logger: false })
    console.log("jami:", app.get(Checkout).billing.total(123456))
    try {
        app.select(CheckoutModule).get(TaxCalculator, { strict: true })
    } catch { console.log("TaxCalculator CheckoutModule'dan ko'rinmaydi ✔") }
    await app.close()
}
main()

