import { Injectable, Module } from "@nestjs/common"
import { ConfigModule, ConfigService } from "@nestjs/config"
import { NestFactory } from "@nestjs/core"

@Injectable()
class UploadsService {
    constructor(private readonly maxSize: number) {}
    check(bytes: number) { return bytes <= this.maxSize ? "qabul qilindi" : `juda katta (max ${this.maxSize / 1024 / 1024} MB)` }
}

@Module({
    imports: [ConfigModule],
    providers: [{ provide: UploadsService, inject: [ConfigService], useFactory: (c: ConfigService) => new UploadsService(c.get("UPLOAD_MAX_MB", 5) * 1024 * 1024) }],
    exports: [UploadsService],
})
class UploadsModule {}

@Module({ imports: [ConfigModule.forRoot({ isGlobal: true, ignoreEnvFile: true, load: [() => ({ UPLOAD_MAX_MB: 2 })] }), UploadsModule] })
class AppModule {}

async function main() {
    const app = await NestFactory.createApplicationContext(AppModule, { logger: false })
    const s = app.get(UploadsService)
    console.log("1 MB:", s.check(1024 * 1024))
    console.log("3 MB:", s.check(3 * 1024 * 1024))
    await app.close()
}
main()

import { Injectable, Module } from "@nestjs/common"
import { NestFactory } from "@nestjs/core"

@Injectable() class A {} @Module({ providers: [A], exports: [A] }) class AModule {}
@Injectable() class B {} @Module({ imports: [AModule], providers: [B], exports: [B] }) class BModule {}
@Module({ imports: [AModule, BModule] }) class AppModule {}

async function main() {
    const app = await NestFactory.createApplicationContext(AppModule, { logger: false })
    const container = (app as any).container
    for (const mod of container.getModules().values()) {
        const name = mod.metatype.name
        if (["InternalCoreModule"].includes(name)) continue
        const imports = [...mod.imports].map((m: any) => m.metatype.name).filter((n: string) => n !== "InternalCoreModule")
        console.log(`${name} → imports: [${imports.join(", ")}]`)
    }
    await app.close()
}
main()

