import { Body, Controller, Injectable, Module, PipeTransform, Post } from "@nestjs/common"
import { APP_PIPE } from "@nestjs/core"

@Injectable()
class Dictionary { bad = ["yomon", "ahmoq"] }

// APP_PIPE orqali ro'yxatdan o'tgani uchun Dictionary inject qilinadi
@Injectable()
class CensorPipe implements PipeTransform {
    constructor(private readonly dict: Dictionary) {}
    transform(value: any) {
        if (value && typeof value.text === "string") {
            for (const w of this.dict.bad) value.text = value.text.replaceAll(w, "***")
        }
        return value
    }
}

@Controller("comments")
class CommentsController {
    @Post() create(@Body() body: { text: string }) { return body }
}

@Module({ controllers: [CommentsController], providers: [Dictionary, { provide: APP_PIPE, useClass: CensorPipe }] })
class AppModule {}

