    const http = await testApp(AppModule)
    await http.post("/comments", { text: "Bu yomon film emas" })
    console.log("app.useGlobalPipes(new CensorPipe(...)) esa DI'dan tashqarida — Dictionary'ni qo'lda berish kerak")
