@Catch()
class AllErrorsFilter implements ExceptionFilter {
    catch(e: unknown, host: ArgumentsHost) {
        const status = e instanceof HttpException ? e.getStatus() : 500
        const message = e instanceof HttpException ? e.message : "Kutilmagan xato"
        host.switchToHttp().getResponse().status(status).json({ ok: false, status, message })
    }
}

