import { CallHandler, Controller, ExecutionContext, Get, Injectable, Module, NestInterceptor } from "@nestjs/common"
import { APP_INTERCEPTOR } from "@nestjs/core"
import { tap } from "rxjs"

@Injectable()
class TimingInterceptor implements NestInterceptor {
    intercept(ctx: ExecutionContext, next: CallHandler) {
        const start = performance.now()
        const res = ctx.switchToHttp().getResponse()
        return next.handle().pipe(tap(() => res.setHeader("X-Response-Time", `${Math.round(performance.now() - start)}ms`)))
    }
}

@Controller()
class AppController {
    @Get("a") a() { return "A" }
    @Get("b") b() { return "B" }
}

@Module({ controllers: [AppController], providers: [{ provide: APP_INTERCEPTOR, useClass: TimingInterceptor }] })
class AppModule {}

async function main() {
    const http = await testApp(AppModule)
    for (const p of ["/a", "/b"]) {
        const r = await http.get(p)
        console.log("  X-Response-Time sarlavhasi bor:", /^[0-9]+ms$/.test(r.headers.get("x-response-time") ?? ""))
    }
    await http.close()
}
main()

