const Public = () => SetMetadata("isPublic", true)
@Injectable() class AuthGuard implements CanActivate {
    constructor(private r: Reflector) {}
    canActivate(ctx: ExecutionContext) {
        if (this.r.getAllAndOverride<boolean>("isPublic", [ctx.getHandler(), ctx.getClass()])) return true
        return ctx.switchToHttp().getRequest().headers.authorization === "Bearer ok"
    }
}
