import { DynamicModule, Inject, Injectable, Module } from "@nestjs/common"
import { NestFactory } from "@nestjs/core"

type RetryOptions = { attempts: number; delayMs: number; factor: number }
const DEFAULTS: RetryOptions = { attempts: 3, delayMs: 100, factor: 2 }
const RETRY_OPTIONS = Symbol("RETRY_OPTIONS")

@Injectable()
class RetryService {
    constructor(@Inject(RETRY_OPTIONS) readonly opts: RetryOptions) {}
    schedule() { return Array.from({ length: this.opts.attempts }, (_, i) => this.opts.delayMs * this.opts.factor ** i) }
}

@Module({})
class RetryModule {
    static forRoot(opts: Partial<RetryOptions> = {}): DynamicModule {
        return { module: RetryModule, providers: [{ provide: RETRY_OPTIONS, useValue: { ...DEFAULTS, ...opts } }, RetryService], exports: [RetryService] }
    }
}

async function main() {
    for (const opts of [{}, { attempts: 5 }, { delayMs: 50, factor: 3 }]) {
        @Module({ imports: [RetryModule.forRoot(opts)] }) class AppModule {}
        const app = await NestFactory.createApplicationContext(AppModule, { logger: false })
        console.log(JSON.stringify(opts), "→ kutishlar (ms):", app.get(RetryService).schedule())
        await app.close()
    }
}
main()

